import { useId, useState, type FormEvent } from 'react';

type Role = 'member' | 'admin' | 'viewer';

const ROLE_OPTIONS: { value: Role; label: string }[] = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function InviteTeamForm() {
  const emailId = useId();
  const hintId = useId();
  const errorId = useId();
  const roleId = useId();
  const notifyId = useId();

  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = EMAIL_PATTERN.test(email.trim());
  const showError = touched && email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);

    if (!canSubmit) {
      return;
    }

    setSubmitted(true);
  };

  const handleReset = () => {
    setEmail('');
    setTouched(false);
    setRole('member');
    setNotify(true);
    setSubmitted(false);
  };

  return (
    <div className="jx-stack jx-stack--md" style={{ maxWidth: '420px' }}>
      {submitted && (
        <div className="jx-alert jx-alert--success" role="status">
          <span className="jx-alert__body">
            Приглашение отправлено на {email.trim()}.
          </span>
          <button
            type="button"
            className="jx-alert__close jx-btn jx-btn--ghost jx-btn--icon"
            aria-label="Закрыть сообщение"
            onClick={() => setSubmitted(false)}
          >
            ✕
          </button>
        </div>
      )}

      <form className="jx-form jx-stack jx-stack--md" onSubmit={handleSubmit} noValidate>
        <div className="jx-field">
          <label className="jx-label" htmlFor={emailId}>
            Email
          </label>
          <input
            id={emailId}
            className={`jx-input${showError ? ' jx-input--error' : ''}`}
            type="email"
            inputMode="email"
            placeholder="name@company.com"
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            onBlur={() => setTouched(true)}
            aria-invalid={showError}
            aria-describedby={showError ? `${hintId} ${errorId}` : hintId}
            required
          />
          <span id={hintId} className="jx-hint">
            Отправим приглашение на этот адрес.
          </span>
          {showError && (
            <span id={errorId} className="jx-field-error" role="alert">
              Похоже, это не email. Проверьте формат: name@company.com
            </span>
          )}
        </div>

        <div className="jx-field">
          <label className="jx-label" htmlFor={roleId}>
            Роль
          </label>
          <select
            id={roleId}
            className="jx-select"
            value={role}
            onChange={(event) => setRole(event.target.value as Role)}
          >
            {ROLE_OPTIONS.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </div>

        <div className="jx-field jx-field--row">
          <label className="jx-switch" htmlFor={notifyId}>
            <input
              id={notifyId}
              type="checkbox"
              className="jx-switch__input"
              checked={notify}
              onChange={(event) => setNotify(event.target.checked)}
            />
            <span className="jx-switch__track" aria-hidden="true">
              <span className="jx-switch__thumb" />
            </span>
            <span className="jx-switch__label">Отправить уведомление на почту</span>
          </label>
        </div>

        <div className="jx-form__actions">
          <button
            type="submit"
            className="jx-btn jx-btn--primary"
            disabled={!canSubmit}
          >
            Отправить приглашение
          </button>
          <button
            type="button"
            className="jx-btn jx-btn--ghost"
            onClick={handleReset}
          >
            Сбросить
          </button>
        </div>
      </form>
    </div>
  );
}

export default InviteTeamForm;

